package net.battlespades.bot;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.BotVectors.*;

/** Atomic movement ownership and bounded, terrain-specific rejection memory shared by all brain roles. */
final class BrainRoutingState {
    private BrainRoutingState(){}
    static final Set<String> HUNT=Set.of("chase_last_seen","investigate_sound");
    static void setGoal(BotBrainState s,BotGoal goal,Vector position,double now){var old=s.goal;boolean same=old!=null&&goal!=null&&old.key().equals(goal.key());if(!same&&old!=null&&goal!=null&&HUNT.contains(old.role())&&HUNT.contains(goal.role())&&distance(old.position(),goal.position())<8)same=true;boolean moved=old!=null&&goal!=null&&flat(old.position(),goal.position())>=3;if(same&&!moved){s.goal=goal;return;}if(same&&goal!=null&&old!=null&&distance(old.position(),goal.position())<16&&(!s.corridor.isEmpty()||s.corridorSearch!=null||s.routeIndex<s.route.size()||s.escapeSearch!=null)){s.goal=goal;return;}if(old==null&&goal==null)return;s.goal=goal;s.navigationPreviousPosition=null;s.planningContext=null;s.planningResults.clear();s.planningWaitAt=null;s.escapeSearch=null;clear(s,now);s.goalBestDistance=goal==null?Double.POSITIVE_INFINITY:flat(goal.position(),position);s.goalProgressAt=now;s.yieldedBreachEdge=null;s.yieldedBreachStartedAt=now;s.dryDetourGoal=null;s.dryDetourUntil=0;s.dryRouteFailures=0;s.corridorSearch=null;s.corridor=List.of();s.corridorIndex=s.corridorJoinIndex=0;s.corridorYieldLocal=false;s.corridorFailedGoal=null;s.corridorRetryAt=now;}
    static void resetBreach(BotBrainState s,double now){s.breachKey=null;s.breachStartedAt=s.nextBreachAt=now;}
    static void clear(BotBrainState s,double now){s.route=List.of();s.routeIndex=0;s.routeTopologyVersion=-1;s.waypointBestDistance=Double.POSITIVE_INFINITY;s.waypointProgressAt=now;resetBreach(s,now);}
    static void remember(BotBrainState s,Edge edge,double now,double lifetime){if(!s.blockedEdges.containsKey(edge)&&s.blockedEdges.size()>=8){var oldest=s.blockedEdges.entrySet().stream().min(Map.Entry.comparingByValue()).orElseThrow().getKey();s.blockedEdges.remove(oldest);s.blockedEdgeSince.remove(oldest);}s.blockedEdges.put(edge,now+Math.max(.1,lifetime));s.blockedEdgeSince.put(edge,now);if(s.corridorSearch!=null)s.corridorSearch.exclude(edge);s.corridor=List.of();s.corridorIndex=0;s.corridorRetryAt=now+1;}
    static void prune(BotBrainState s,double now){for(var edge:new ArrayList<>(s.blockedEdges.keySet()))if(s.blockedEdges.get(edge)<=now){s.blockedEdges.remove(edge);s.blockedEdgeSince.remove(edge);}}
    static void note(BotBrainState s,RouteStep step,double now){List<Object> key=List.of((int)Math.floor(step.waypoint().x()),(int)Math.floor(step.waypoint().y()),(int)Math.rint(step.waypoint().z()),step.affordance());if(!key.equals(s.stepKey)){s.stepKey=key;s.stepSince=now;}}
    static boolean stalled(BotBrainState s,double now,double period){return now-s.stepSince>=period;}
    static Vector goalPlace(BotNavigationWorld w,Vector p){var floor=w.goalSurface(p,false);return floor==null?p:new Vector(p.x(),p.y(),floor.position().z());}
    static void invalidate(BotNavigationWorld w,BotBrainState s,Vector position,double now,Double lifetime){if(s.routeIndex>=s.route.size())return;var step=s.route.get(s.routeIndex);if(step.affordance()==Affordance.JUMP&&step.entryEdge()!=null){remember(s,step.entryEdge(),now,lifetime==null?step.entryEdge().source().z()>=238?20:12:lifetime);return;}if(step.breach()!=null){remember(s,new Edge(step.breach().source(),step.breach().destination()),now,lifetime==null?60:lifetime);return;}var current=w.surface((int)Math.floor(position.x()),(int)Math.floor(position.y()),position.z(),8,true);if(current==null)return;var point=step.waypoint();var target=w.surface((int)Math.floor(point.x()),(int)Math.floor(point.y()),point.z(),8,true);if(target!=null&&step.affordance()==Affordance.JUMP){remember(s,new Edge(new Cell(current.x(),current.y(),current.supportZ()),new Cell(target.x(),target.y(),target.supportZ())),now,lifetime==null?current.supportZ()>=238?20:12:lifetime);return;}double dx=point.x()-position.x(),dy=point.y()-position.y();int sx=Math.abs(dx)>=Math.abs(dy)?dx>0?1:-1:0,sy=Math.abs(dx)>=Math.abs(dy)?0:dy>0?1:-1;var neighbor=w.surface(current.x()+sx,current.y()+sy,current.position().z(),8,current.supportZ()>=238||step.affordance()==Affordance.SWIM);if(neighbor!=null)remember(s,new Edge(new Cell(current.x(),current.y(),current.supportZ()),new Cell(neighbor.x(),neighbor.y(),neighbor.supportZ())),now,lifetime==null?current.supportZ()>=238?20:60:lifetime);}
}
